import type { MetadataRoute } from 'next';

/**
 * Web app manifest (/manifest.webmanifest). The icons are the favicon set in
 * public/brand/favicon, generated by scripts/brand/make-brand-assets.py;
 * colors are the canvas token (docs/09 §2), matching the viewport themeColor.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'Orqestra',
    short_name: 'Orqestra',
    description: 'The ATS built for the age of AI.',
    start_url: '/',
    display: 'standalone',
    background_color: '#F5F4F2',
    theme_color: '#F5F4F2',
    icons: [
      { src: '/brand/favicon/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/brand/favicon/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      {
        src: '/brand/favicon/icon-512-maskable.png',
        sizes: '512x512',
        type: 'image/png',
        purpose: 'maskable',
      },
    ],
  };
}
